import math
def priority(task, state, m=2.0, k=1.0, f_align=1.0, f_var=1.0, f_sv=1.0):
    est = max(task.estimated_runtime, 1e-6)
    if task.task_type == 'alignment':
        tf = f_align
    elif task.task_type == 'variant_calling':
        tf = f_var
    else:
        tf = f_sv
    base = tf / est
    if task.tenant == 'premium':
        slack = max(0.0, task.due - state.now - est)
        return base * (1.0 + m * math.exp(-slack / max(k * state.mean_est, 1e-6)))
    return base
