import math

def priority(task, state, alpha_p=0.5, alpha_s=0.5, m=2.0, k=1.0, b=0.5, q=10.0,
             f_align=1.0, f_var=1.0, f_sv=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    if task.task_type == 'alignment':
        tf = f_align
    elif task.task_type == 'variant_calling':
        tf = f_var
    else:
        tf = f_sv
    if task.tenant == 'premium':
        slack = max(0.0, task.due - state.now - est)
        base = tf / max(est ** alpha_p, 1e-6)
        return base * m * math.exp(-slack / max(k * est, 1e-6))
    else:
        base = tf / max(est ** alpha_s, 1e-6)
        age = 1.0 + b * wait / est * min(1.0, state.queue_len / max(q, 1e-6))
        return base * age
