import math
def priority(task, state, guard=1e6, k=2.0, b=0.5, c=0.5, a=1.0, p=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    wait = state.now - task.release
    weight = max(task.weight, 1e-6)
    slack = task.due - est - state.now
    if task.tenant == 'premium':
        if slack <= c * mean_est:
            return guard + weight / est
        return 2.0 * weight / est * math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6)) * (1.0 + b * wait / est)
    else:
        return weight / est * ((1.0 + b * wait / est) ** p) * (1.0 + a * wait / mean_est)
