import math
def priority(task, state, guard=1e6, mid=1000.0, k=2.0, b=0.5, c1=0.25, c2=1.0, a=1.0, h=5.0, m=2.0):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    weight = max(task.weight, 1e-6)
    slack = task.due - est - state.now
    if task.tenant == 'premium':
        if slack <= c1 * mean_est:
            return guard + weight / est
        if slack <= c2 * mean_est:
            return mid + weight / max(slack, 1e-6)
        return m * weight / est * math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6)) * (1.0 + b * wait / est)
    else:
        due_factor = math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6))
        age = (1.0 + b * wait / est) * (1.0 + a * wait / mean_est)
        starve = 1.0 + a * max(0.0, wait / mean_est - h)
        return weight / est * due_factor * age * starve

